function settingsContent(){$('#settings-dialog').innerHTML=`<div class="dialog-head"><h2>${t('Make it yours','আপনার মতো সাজান')}</h2><button class="icon-button" data-action="close-settings" aria-label="${t('Close settings','সেটিংস বন্ধ করুন')}">${I('close')}</button></div><div class="dialog-body"><div class="settings-row"><div><strong>${t('Language','ভাষা')}</strong><small>${t('All pages and information','সব পাতা ও তথ্য')}</small></div><select id="settings-language" aria-label="${t('Language','ভাষা')}"><option value="en" ${lang==='en'?'selected':''}>English</option><option value="bn" ${lang==='bn'?'selected':''}>বাংলা</option></select></div><div class="settings-row"><div><strong>${t('Appearance','থিম')}</strong><small>${t('Comfort for day and night','দিন ও রাতের জন্য')}</small></div><select id="theme-select" aria-label="${t('Theme','থিম')}"><option value="light" ${theme==='light'?'selected':''}>${t('Light','হালকা')}</option><option value="dark" ${theme==='dark'?'selected':''}>${t('Dark','গাঢ়')}</option></select></div><div class="settings-row"><div><strong>${t('Reading size','লেখার আকার')}</strong><small>${t('Choose comfortable text','স্বাচ্ছন্দ্যে পড়ুন')}</small></div><select id="font-size-select" aria-label="${t('Text size','লেখার আকার')}"><option value="normal" ${font==='normal'?'selected':''}>${t('Normal','স্বাভাবিক')}</option><option value="large" ${font!=='normal'?'selected':''}>${t('Large','বড়')}</option></select></div><button class="btn secondary full" data-action="reset-date">${t('Reset date widget position','তারিখের অবস্থান ফিরিয়ে আনুন')}</button><p class="form-hint" style="margin-top:15px">${t('Preferences are saved in this browser. Use the date handle to move the bilingual date widget.','পছন্দ এই ব্রাউজারে থাকে। তারিখের হ্যান্ডেল ধরে দুই ভাষার তারিখ সরাতে পারবেন।')}</p></div>`;}
