document.addEventListener('keydown',e=>{if((e.key==='/'&&!e.ctrlKey&&!e.metaKey||e.key==='k'&&(e.ctrlKey||e.metaKey))&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();if(!$('#search-dialog').open&&!$('#settings-dialog').open)openSearch();}});
