let riceQuery='',riceSeason='all',riceTrait='all',riceInstitution='all',bioQuery='',bioGroup='all';
function learningSources(sources=[]){const unique=[...new Map(sources.filter(Boolean).map(s=>[s.url,s])).values()];return `<div class="library-sources">${unique.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${I('external')}</a>`).join('')}</div>`;}
function learningCards(){return `<div class="grid two learning-cards">${LEARNING_TOPICS.map(c=>`<a class="card card-pad learning-topic" href="#${c.route}"><span class="topic-symbol">${I(c.icon)}</span><div class="mini-label">${esc(L(c.label))}</div><h3>${esc(L(c.title))}</h3><p>${esc(L(c.description))}</p><span class="link">${t('Open guide','নির্দেশিকা খুলুন')}${I('arrow')}</span></a>`).join('')}</div>`;}
function learningHomeSection(){return `<section class="section learning-home">${sectionHead(t('Practical learning','ব্যবহারিক কৃষিশিক্ষা'),t('Rice, rooftops and biological care','ধান, ছাদবাগান ও জৈব পরিচর্যা'),t('Browse varieties and use source-linked growing guides.','জাত বাছুন এবং সূত্রসহ চাষের নির্দেশিকা পড়ুন।'),'guides',t('All learning guides','সব নির্দেশিকা'))}${learningCards()}</section>`;}
function guidesPage(){return `<div class="wrap">${pageTop(t('Cultivation & biological care','চাষ ও জৈব পরিচর্যা'),t('Practical guidance for rice fields, rooftop containers and biological pest management.','ধানের জমি, ছাদের টব ও জৈব বালাই ব্যবস্থাপনার ব্যবহারিক নির্দেশিকা।'))}<div class="page-content">${learningCards()}<section class="card card-pad learning-reference"><h2>${t('Plan with the right source','উপযুক্ত সূত্র দিয়ে পরিকল্পনা করুন')}</h2><p>${t('Choose the crop and season first, then check the local variety, field or roof conditions and the exact product label. Each guide includes its references and practical limits.','আগে ফসল ও মৌসুম, পরে স্থানীয় জাত, জমি বা ছাদের অবস্থা এবং নির্দিষ্ট পণ্যের লেবেল মিলান। প্রতিটি নির্দেশিকায় তথ্যসূত্র ও ব্যবহারের সীমা আছে।')}</p><div class="flex-links">${link('crop/rice',t('Rice cultivation','ধান চাষ'))}${link('crops',t('All crop guides','সব ফসলের নির্দেশিকা'))}${link('pests',t('Pest & disease library','পোকা–রোগের পরিচিতি'))}</div></section><section class="card card-pad learning-reference"><h2>${t('Apps & further reading','অ্যাপ ও আরও পড়ার সূত্র')}</h2><p>${L(APP_REVIEW_NOTE)}</p>${learningSources(APP_REFERENCES)}<p class="guide-note">${t('Source review: 9 November 2026. Varieties shown here are selected examples; use the full official catalogues for additional choices.','সূত্র পর্যালোচনা: ৯ নভেম্বর ২০২৬। এখানে নির্বাচিত জাতের উদাহরণ আছে; আরও জাতের জন্য সম্পূর্ণ সরকারি তালিকা দেখুন।')}</p></section></div></div>`;}
function riceVarietiesPage(){return `<div class="wrap">${pageTop(t('Rice varieties: choose by season','ধানের জাত: মৌসুম অনুযায়ী বাছুন'),t('26 selected BRRI and BINA varieties, with life-cycle notes, special traits and direct official sources.','ব্রি–বিনার নির্বাচিত ২৬টি জাত: জীবনকাল, বিশেষ বৈশিষ্ট্য ও সরাসরি সরকারি তথ্যসূত্র।'),['guides',t('Learning guides','চাষের নির্দেশিকা')])}<div class="page-content"><div class="rice-intro card card-pad"><p>${t('Aus, Aman and Boro are growing seasons. Published life cycle normally includes the nursery period and varies with planting date and site. Tolerance depends on the type, level and timing of stress; it is not immunity.','আউশ, আমন ও বোরো চাষের মৌসুম। প্রকাশিত জীবনকালে সাধারণত বীজতলার সময়ও থাকে; বপনের দিন ও স্থানভেদে বদলায়। সহনশীলতা চাপের ধরন, মাত্রা ও সময়নির্ভর; পুরোপুরি ক্ষতিমুক্ত থাকার নিশ্চয়তা নয়।')}</p>${link('crop/rice',t('Read the full rice growing guide','ধানের বিস্তারিত চাষ নির্দেশিকা পড়ুন'))}</div><div class="rice-filters"><div><label for="rice-search">${t('Name or feature','নাম বা বৈশিষ্ট্য')}</label><input id="rice-search" type="search" value="${esc(riceQuery)}" placeholder="${t('Try BRRI 49, BINA or zinc','ব্রি ৪৯, বিনা বা জিংক লিখুন')}"></div><div><label for="rice-season">${t('Season','মৌসুম')}</label><select id="rice-season">${[['all',bi('All seasons','সব মৌসুম')],...Object.entries(riceSeasons)].map(([k,n])=>`<option value="${k}" ${riceSeason===k?'selected':''}>${L(n)}</option>`).join('')}</select></div><div><label for="rice-trait">${t('Feature','বিশেষ বৈশিষ্ট্য')}</label><select id="rice-trait">${[['all',bi('All features','সব বৈশিষ্ট্য')],...Object.entries(riceTraits)].map(([k,n])=>`<option value="${k}" ${riceTrait===k?'selected':''}>${L(n)}</option>`).join('')}</select></div><div><label for="rice-institution">${t('Institution','প্রতিষ্ঠান')}</label><select id="rice-institution">${[['all',t('Both institutions','দুই প্রতিষ্ঠান')],['BRRI',t('BRRI','ব্রি')],['BINA',t('BINA','বিনা')]].map(([k,n])=>`<option value="${k}" ${riceInstitution===k?'selected':''}>${n}</option>`).join('')}</select></div></div><p id="rice-count" class="results-count" role="status" aria-live="polite"></p><div id="rice-results"></div><section class="card card-pad learning-reference"><h2>${t('Full official catalogues','সম্পূর্ণ সরকারি জাততালিকা')}</h2>${learningSources(RICE_CATALOGUES)}</section></div></div>`;}
function normaliseLearning(text){return String(text).toLowerCase().replace(/[০-৯]/g,d=>'০১২৩৪৫৬৭৮৯'.indexOf(d)).replace(/[-–—]/g,' ').replace(/brri\s*dhan/g,'brri dhan').replace(/ব্রিধান/g,'ব্রি ধান').replace(/([\p{L}\p{M}])(\d)/gu,'$1 $2');}
function renderRiceVarieties(){const tokens=normaliseLearning(riceQuery).trim().split(/\s+/).filter(Boolean);const results=RICE_VARIETIES.filter(v=>(riceSeason==='all'||v.seasons.includes(riceSeason))&&(riceTrait==='all'||v.tags.includes(riceTrait))&&(riceInstitution==='all'||v.institution===riceInstitution)&&tokens.every(token=>/^\d+$/.test(token)?(normaliseLearning(JSON.stringify(v.name)).match(/\d+/g)||[]).includes(token):normaliseLearning(JSON.stringify([v.name,v.features,v.duration,v.institution,v.seasons.map(s=>riceSeasons[s]),v.tags.map(s=>riceTraits[s])])).includes(token)));$('#rice-count').textContent=`${num(results.length)} ${t('varieties','টি জাত')}`;$('#rice-results').innerHTML=results.length?`<div class="grid three">${results.map(v=>`<a class="card card-pad variety-card" href="#rice-variety/${v.id}"><div class="variety-heading"><span class="topic-symbol small">${I('grain')}</span><span class="mini-label">${esc(v.institution)}</span></div><h2>${esc(L(v.name))}</h2><div class="variety-tags">${v.seasons.map(s=>`<span class="tag">${L(riceSeasons[s])}</span>`).join('')}${v.tags.map(s=>`<span class="soft-tag">${L(riceTraits[s])}</span>`).join('')}</div><p class="variety-duration">${esc(L(v.duration))}</p><p class="pest-summary">${esc(L(v.features))}</p><span class="link">${t('Variety details','জাতের বিস্তারিত')}${I('arrow')}</span></a>`).join('')}</div>`:`<div class="empty"><p>${t('No variety matches these filters. Change a filter or clear the search.','এই বাছাইয়ে জাত পাওয়া যায়নি। বাছাই বদলান বা অনুসন্ধান মুছুন।')}</p><button class="btn secondary" data-action="reset-rice">${t('Reset filters','বাছাই আবার শুরু করুন')}</button></div>`;}
function riceVarietyPage(id){const v=RICE_VARIETIES.find(v=>v.id===id);if(!v)return notFound();return `<div class="wrap">${pageTop(L(v.name),t('Published variety characteristics and local planning','প্রকাশিত জাতের বৈশিষ্ট্য ও স্থানীয় পরিকল্পনা'),['rice-varieties',t('Rice varieties','ধানের জাত')])}<div class="page-content detail-layout"><div class="stack"><section class="card card-pad"><div class="variety-heading"><span class="topic-symbol">${I('grain')}</span><strong>${esc(v.institution)}</strong></div><h2>${t('Season & life cycle','মৌসুম ও জীবনকাল')}</h2><div class="variety-tags">${v.seasons.map(s=>`<span class="tag">${L(riceSeasons[s])}</span>`).join('')}${v.tags.map(s=>`<span class="soft-tag">${L(riceTraits[s])}</span>`).join('')}</div><p>${esc(L(v.duration))}</p>${v.height||v.yield?`<dl class="variety-metrics">${v.height?`<div><dt>${t('Published height','প্রকাশিত উচ্চতা')}</dt><dd>${esc(L(v.height))}</dd></div>`:''}${v.yield?`<div><dt>${t('Published yield example','প্রকাশিত ফলনের উদাহরণ')}</dt><dd>${esc(L(v.yield))}</dd></div>`:''}</dl>`:''}<p class="guide-note">${t('Life cycle includes the nursery period. Published paddy yield is a reference for the stated conditions; actual field results depend on site, weather and management. Match sowing and maturity to the official variety guide and your district.','জীবনকালে বীজতলার সময়ও থাকে। প্রকাশিত ফলন বর্ণিত অবস্থায় ধানের উদাহরণ; জমি, আবহাওয়া ও ব্যবস্থাপনায় মাঠের ফলন বদলায়। সরকারি জাত নির্দেশিকা ও জেলার সঙ্গে বপন ও পাকার সময় মেলান।')}</p></section>${guideSection(t('Variety characteristics','জাতের বৈশিষ্ট্য'),L(v.features))}${guideSection(t('Before choosing seed','বীজ কেনার আগে'),t('Check the named variety on the certified pack, seed lot, expiry and germination information. Match land height, irrigation, salinity or flood history and the harvest window. A salt-tolerant or submergence-tolerant label applies to particular conditions, not every stress. Hybrid seed requires its own production guidance and fresh genuine seed supply.','প্রত্যয়িত প্যাকেটে জাতের নাম, বীজের লট, মেয়াদ ও অঙ্কুরোদ্গমের তথ্য মিলান। জমির উচ্চতা, সেচ, লবণ বা বন্যার ইতিহাস ও সংগ্রহের সময় মিলিয়ে নিন। লবণ বা নিমজ্জনসহনশীলতা নির্দিষ্ট অবস্থার জন্য, সব চাপের জন্য নয়। হাইব্রিডে নিজস্ব চাষ নির্দেশিকা ও আসল নতুন বীজের সরবরাহ প্রয়োজন।'))}<section class="card card-pad"><h2>${t('Official source','সরকারি তথ্যসূত্র')}</h2>${learningSources([v.source])}</section></div><aside class="stack"><section class="card card-pad"><h3>${t('Put the variety into practice','জাতটি চাষের পরিকল্পনায় নিন')}</h3>${link('crop/rice',t('Rice: planting to harvest','ধান: বপন থেকে সংগ্রহ'))}${link('pests',t('Rice pest & disease guidance','ধানের পোকা–রোগ নির্দেশিকা'))}${link('rice-varieties',t('Compare other varieties','অন্য জাত মিলিয়ে দেখুন'))}</section></aside></div></div>`;}
function rooftopPage(){return `<div class="wrap">${pageTop(L(ROOFTOP_GUIDE.title),L(ROOFTOP_GUIDE.intro),['guides',t('Learning guides','চাষের নির্দেশিকা')])}<div class="page-content"><section class="card card-pad roof-overview"><div class="roof-sketch" aria-hidden="true">${['plant','sprout','leaf','plant'].map(ic=>`<span>${I(ic)}</span>`).join('')}</div><div><span class="eyebrow">${t('Plan → plant → care','পরিকল্পনা → রোপণ → পরিচর্যা')}</span><h2>${t('Start small, keep the roof accessible','অল্প গাছে শুরু, চলাচল রাখুন খোলা')}</h2><p>${t('Roof capacity, water drainage and safe access come before heavy pots or permanent beds. Then choose a few crops suited to your available light and care time.','ভারী টব বা স্থায়ী বেডের আগে ছাদের সক্ষমতা, পানি বের হওয়া ও নিরাপদ চলাচল নিশ্চিত করুন। তারপর আলো ও পরিচর্যার সময় অনুযায়ী অল্প কিছু ফসল বাছুন।')}</p></div></section><div class="roof-layout"><aside class="card card-pad guide-contents"><h2>${t('In this guide','এই নির্দেশিকায়')}</h2><ol>${ROOFTOP_GUIDE.sections.map(s=>`<li><button data-learning-jump="roof-${s.id}">${esc(L(s.title))}</button></li>`).join('')}</ol></aside><div class="stack">${ROOFTOP_GUIDE.sections.map((s,i)=>`<section class="card card-pad guide-section" tabindex="-1" id="roof-${s.id}"><span class="eyebrow">${num(i+1)} / ${num(ROOFTOP_GUIDE.sections.length)}</span><h2>${esc(L(s.title))}</h2><p>${esc(L(s.text))}</p>${learningSources([s.source])}</section>`).join('')}</div></div><section class="section"><h2>${t('Start with a few suitable crops','শুরু করুন কয়েকটি উপযুক্ত ফসলে')}</h2><p class="learning-lead">${t('Choose from these after checking light, container size and local season. Climbing crops need stable supports; fruiting crops need more room and light than small greens.','আলো, পাত্রের আকার ও স্থানীয় মৌসুম মিলিয়ে বাছুন। লতানো গাছে স্থির ঠেস লাগে; ছোট শাকের চেয়ে ফলের গাছে জায়গা ও আলো বেশি লাগে।')}</p><div class="grid four roof-crops">${cropCards(ROOFTOP_GUIDE.starterCrops)}</div></section><div class="flex-links">${link('biopesticides',t('Biological pest management','জৈব বালাই ব্যবস্থাপনা'),'btn secondary')}${link('category/indoor',t('Indoor plant care','ইনডোর গাছের পরিচর্যা'),'btn secondary')}</div></div></div>`;}
function biopesticidesPage(){const o=BIO_LIBRARY.overview;return `<div class="wrap">${pageTop(L(o.title),L(o.intro),['guides',t('Learning guides','চাষের নির্দেশিকা')])}<div class="page-content"><div class="bio-principles grid three">${[['Match the target','লক্ষ্য বালাই মিলান',t('Crop, pest species, life stage, strain and formulation determine the choice.','ফসল, বালাইয়ের প্রজাতি, জীবনধাপ, স্ট্রেইন ও ফরমুলেশন মিলিয়ে বাছুন।')],['Check the product','পণ্য যাচাই করুন',L(o.viability)],['Read the label','লেবেল পড়ুন',L(o.label)]].map(([a,b,p])=>`<section class="card card-pad"><h2>${t(a,b)}</h2><p>${esc(p)}</p></section>`).join('')}</div><div class="toolbar learning-toolbar"><label class="sr-only" for="bio-search">${t('Find a biological method','জৈব পদ্ধতি খুঁজুন')}</label><input id="bio-search" type="search" value="${esc(bioQuery)}" placeholder="${t('Try Bt, neem, Trichoderma or aphid','Bt, নিম, ট্রাইকোডার্মা বা জাব লিখুন')}"><label class="sr-only" for="bio-group">${t('Method type','পদ্ধতির ধরন')}</label><select id="bio-group">${[['all',bi('All methods','সব পদ্ধতি')],...Object.entries(bioGroups)].map(([k,n])=>`<option value="${k}" ${bioGroup===k?'selected':''}>${L(n)}</option>`).join('')}</select></div><p id="bio-count" class="results-count" role="status" aria-live="polite"></p><div id="bio-results"></div><section class="card card-pad learning-reference"><h2>${t('Use biological methods thoughtfully','বুঝে জৈব পদ্ধতি ব্যবহার করুন')}</h2><p>${esc(L(o.limits))}</p>${learningSources(o.sources)}</section></div></div>`;}
function renderBioMethods(){const tokens=normaliseLearning(bioQuery).trim().split(/\s+/).filter(Boolean);const results=BIO_LIBRARY.items.filter(b=>(bioGroup==='all'||b.group===bioGroup)&&tokens.every(token=>normaliseLearning(JSON.stringify([b.name,b.targets,b.use,bioGroups[b.group],b.pestKeys.map(k=>pestByKey(k)?.[lang])])).includes(token)));$('#bio-count').textContent=`${num(results.length)} ${t('methods','টি পদ্ধতি')}`;$('#bio-results').innerHTML=results.length?`<div class="grid three">${results.map(b=>`<a class="card card-pad bio-card" href="#biopesticide/${b.id}"><div class="variety-heading"><span class="topic-symbol small">${I(b.group==='physical'?'target':b.group==='beneficial'?'bug':'leaf')}</span><span class="mini-label">${esc(L(bioGroups[b.group]))}</span></div><h2>${esc(L(b.name))}</h2><p>${esc(L(b.targets))}</p><span class="link">${t('Use, limits & storage','ব্যবহার, সীমা ও সংরক্ষণ')}${I('arrow')}</span></a>`).join('')}</div>`:`<div class="empty"><p>${t('No method matches. Try a shorter name or reset filters.','পদ্ধতি পাওয়া যায়নি। ছোট নাম লিখুন বা বাছাই আবার শুরু করুন।')}</p><button class="btn secondary" data-action="reset-bio">${t('Reset filters','বাছাই আবার শুরু করুন')}</button></div>`;}
function bioMethodPage(id){const b=BIO_LIBRARY.items.find(b=>b.id===id);if(!b)return notFound();return `<div class="wrap">${pageTop(L(b.name),L(bioGroups[b.group]),['biopesticides',t('Biological management','জৈব ব্যবস্থাপনা')])}<div class="page-content detail-layout"><div class="stack">${[[t('Targets & suitable situations','লক্ষ্য বালাই ও উপযুক্ত অবস্থা'),b.targets],[t('How it is used','ব্যবহারের পদ্ধতি'),b.use],[t('Limits & precautions','সীমাবদ্ধতা ও সতর্কতা'),b.limits],[t('Storage & handling','সংরক্ষণ ও ব্যবহার'),b.storage]].map(([title,text])=>guideSection(title,L(text))).join('')}<section class="card card-pad"><h2>${t('Read the matching pest guide','সংশ্লিষ্ট বালাইয়ের নির্দেশিকা পড়ুন')}</h2><p>${t('These links explain the pest and relevant management; the crop–product label still decides where a formulation may be used.','এখানে বালাই ও ব্যবস্থাপনা আছে; নির্দিষ্ট পণ্য কোন ফসলে দেওয়া যাবে তা ফসল–পণ্যের লেবেলে ঠিক হয়।')}</p>${relatedPests(b.pestKeys)}</section><section class="card card-pad"><h2>${t('References','তথ্যসূত্র')}</h2>${learningSources(b.sources)}</section></div><aside class="stack"><section class="card card-pad"><h3>${t('Before applying','প্রয়োগের আগে')}</h3><p>${esc(L(BIO_LIBRARY.overview.label))}</p><p>${t('Check whether the exact method is suitable for your field or containers; a biological origin alone does not establish safety or organic certification.','নির্দিষ্ট পদ্ধতি আপনার জমি বা টবের জন্য উপযুক্ত কি না দেখুন; জৈব উৎস হলেই নিরাপত্তা বা জৈব সনদ নিশ্চিত হয় না।')}</p>${link('biopesticides',t('All 14 methods','সব ১৪টি পদ্ধতি'))}${link('rooftop',t('Rooftop growing guide','ছাদবাগানের নির্দেশিকা'))}</section></aside></div></div>`;}
document.addEventListener('click',e=>{const jump=e.target.closest('[data-learning-jump]');if(jump){const target=document.getElementById(jump.dataset.learningJump);if(target){target.scrollIntoView({behavior:'instant',block:'start'});target.focus({preventScroll:true});}return;}const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='reset-rice'){riceQuery='';riceSeason='all';riceTrait='all';riceInstitution='all';render();}if(a.dataset.action==='reset-bio'){bioQuery='';bioGroup='all';render();}});
document.addEventListener('input',e=>{if(e.target.id==='rice-search'){riceQuery=e.target.value;renderRiceVarieties();}if(e.target.id==='bio-search'){bioQuery=e.target.value;renderBioMethods();}});
document.addEventListener('change',e=>{if(e.target.id==='rice-season'){riceSeason=e.target.value;renderRiceVarieties();}if(e.target.id==='rice-trait'){riceTrait=e.target.value;renderRiceVarieties();}if(e.target.id==='rice-institution'){riceInstitution=e.target.value;renderRiceVarieties();}if(e.target.id==='bio-group'){bioGroup=e.target.value;renderBioMethods();}});

function learningRiceShortcuts(){return `<div class="learning-shortcuts">${link('rice-varieties',t('Choose a rice variety','ধানের জাত বাছুন'))}${link('biopesticides',t('Biological management','জৈব ব্যবস্থাপনা'))}${link('guides',t('All learning guides','সব চাষ নির্দেশিকা'))}</div>`;}
function learningBioShortcut(){return `<div class="learning-shortcuts">${link('biopesticides',t('Explore 14 biological methods: targets, use and limits','১৪টি জৈব পদ্ধতি: লক্ষ্য, ব্যবহার ও সীমাবদ্ধতা জানুন'))}</div>`;}
function learningRoofShortcut(){return `<div class="learning-shortcuts">${link('rooftop',t('Plan a rooftop garden step by step','ধাপে ধাপে ছাদবাগানের পরিকল্পনা করুন'))}</div>`;}


setInterval(updateDate,30000);
render();

function photoCredit(file){const c=PHOTO_CREDITS[file];return c?`<figcaption class="photo-credit"><a href="${esc(c.page)}" target="_blank" rel="noopener noreferrer">${esc(c.title.replace(/^File:/,''))}</a> · ${esc(c.author)} · <a href="${esc(c.licenseUrl||c.page)}" target="_blank" rel="noopener noreferrer">${esc(c.license)}</a> · ${t('Resized for display','প্রদর্শনের জন্য আকার পরিবর্তিত')}</figcaption>`:'';}
function guideSection(title,text,extra=''){return `<section class="card card-pad guide-section"><h2>${esc(title)}</h2><p>${esc(text)}</p>${extra}</section>`;}
function pestByKey(key){if(!/^[pd]\d+$/.test(key||''))return null;return (key[0]==='p'?pestData:diseases)[Number(key.slice(1))]||null;}
function relatedPests(keys){return `<div class="guide-related">${keys.filter(k=>pestByKey(k)).map(k=>link('pest/'+k,pestByKey(k)[lang].name)).join('')}</div>`;}
function pestPage(key){const p=pestByKey(key),g=PEST_GUIDES[key];if(!p||!g)return notFound();const d=p[lang];return `<div class="wrap">${pageTop(d.name,d.sci,['pests',t('Pests & diseases','পোকা ও রোগ')])}<div class="page-content detail-layout"><div class="stack"><section class="card guide-gallery">${(p.images||[]).map((file,i)=>`<figure><a href="${esc(file)}" target="_blank" rel="noopener" aria-label="${t('Open full image','পূর্ণ ছবি দেখুন')}"><img src="${esc(file)}" alt="${esc(d.name)} · ${t('reference image','পরিচিতিমূলক ছবি')} ${i+1}" loading="${i?'lazy':'eager'}" decoding="async" width="960" height="640"></a>${photoCredit(file)}</figure>`).join('')}<p class="photo-context">${t('Reference photographs; similar symptoms can have different causes. Open an image to view it larger.','পরিচিতিমূলক ছবি; একই রকম লক্ষণের কারণ আলাদা হতে পারে। আরও বড় দেখতে ছবিতে চাপুন।')}</p></section>${guideSection(t('Hosts, signs & damage','আক্রান্ত ফসল, লক্ষণ ও ক্ষতি'),d.crop+' — '+d.damage)}${guideSection(t('Identify before treating','ব্যবস্থাপনার আগে শনাক্ত করুন'),L(g.identify))}${guideSection(t('Field checks & supportive management','মাঠে পর্যবেক্ষণ ও সহায়ক ব্যবস্থাপনা'),L(g.monitor))}${guideSection(t('Biological & biopesticide management','জৈব ও জৈব বালাইনাশক ব্যবস্থাপনা'),L(g.bio),`<p class="guide-note">${L(BIO_NOTE)}</p>`)}${guideSection(t('Chemical management','রাসায়নিক ব্যবস্থাপনা'),L(g.chemical),`<div class="label-note"><h3>${t('Before using a product','পণ্য ব্যবহারের আগে')}</h3><p>${L(PEST_LABEL_NOTE)}</p></div>`)}${guideSection(t('Check the result','ফলাফল যাচাই'),t('Record the date, crop stage, live pest count and new injury before treatment. Revisit the same marked plants and compare fresh damage; old spots and holes do not disappear. If damage spreads, take clear photos of the whole plant, both leaf surfaces and roots/stems as appropriate to the local agriculture office.','ব্যবস্থাপনার আগে তারিখ, ফসলের ধাপ, জীবিত পোকার সংখ্যা ও নতুন ক্ষতি লিখুন। একই চিহ্নিত গাছে নতুন ক্ষতি মিলিয়ে দেখুন; পুরোনো দাগ-গর্ত মুছে যায় না। ক্ষতি বাড়লে পুরো গাছ, পাতার দুই পিঠ ও প্রয়োজনমতো শিকড়/কাণ্ডের পরিষ্কার ছবি নিয়ে স্থানীয় কৃষি অফিসে জানান।'))}<section class="card card-pad"><h2>${t('Sources & review','তথ্যসূত্র ও পর্যালোচনা')}</h2><p>${t('Reviewed 9 November 2026. International sources support identification and IPM; they do not authorise pesticide use in Bangladesh. Historical registration lists and manufacturer information require confirmation against the current product label.','পর্যালোচনা: ৯ নভেম্বর ২০২৬। আন্তর্জাতিক উৎস শনাক্তকরণ ও আইপিএমের সহায়ক; সেগুলো বাংলাদেশে বালাইনাশক ব্যবহারের অনুমোদন নয়। পুরোনো নিবন্ধন ও প্রস্তুতকারকের তথ্য বর্তমান পণ্যের লেবেলের সঙ্গে মিলাতে হবে।')}</p>${librarySources([...new Set([...(p.sources||[]),...g.refs])])}</section></div><aside class="stack"><div class="card card-pad"><span class="eyebrow">${t('One complete guide','এক পাতায় পুরো নির্দেশিকা')}</span><h3>${t('Diagnose → manage → review','চিনুন → ব্যবস্থা নিন → যাচাই করুন')}</h3><p>${t('Start with prevention and the least disruptive effective option. Product examples are crop-specific, not shopping endorsements.','আগে প্রতিরোধ ও কার্যকর কম ক্ষতিকর উপায় নিন। পণ্যের উদাহরণ ফসলনির্দিষ্ট, কেনার সুপারিশ নয়।')}</p>${link('help',t('Prepare a question','প্রশ্ন প্রস্তুত করুন'))}${link('pests',t('All 32 pest & disease guides','সব ৩২টি পোকা–রোগ নির্দেশিকা'))}${link('crops',t('Cultivation guides','চাষের নির্দেশিকা'))}</div></aside></div></div>`;}
function cropPage(id){if(!cropData[id]||!CROP_GUIDES[id])return notFound();const d=cropData[id][lang],ex=CROP_EXTRA[id],g=CROP_GUIDES[id];return `<div class="wrap">${pageTop(clean(d.title),d.text,['crops',t('Crops','ফসল')])}${id==='rice'?learningRiceShortcuts():''}<div class="page-content detail-layout"><div class="stack"><section class="card"><figure class="crop-guide-figure">${cropArt(id,true)}${photoCredit(CROP_IMAGES[id])}</figure></section><section class="card card-pad"><h2>${t('Season & site','মৌসুম ও জমি')}</h2><div class="facts"><div class="fact"><small>${t('Season','মৌসুম')}</small><strong>${L(ex.season)}</strong></div><div class="fact"><small>${t('Land & water','জমি ও পানি')}</small><strong>${L(ex.soil)}</strong></div></div><p class="guide-note">${t('A practical cultivation guide. Exact sowing dates, spacing, seed rate and fertilizer quantities depend on the named variety, district, soil test and production system; use the linked Bangladesh guidance with your local agriculture office.','ব্যবহারিক চাষ নির্দেশিকা। নির্দিষ্ট বপনের দিন, দূরত্ব, বীজহার ও সারের পরিমাণ জাত, জেলা, মাটি পরীক্ষা ও চাষপদ্ধতি অনুযায়ী বদলায়; সংযুক্ত বাংলাদেশি নির্দেশিকা স্থানীয় কৃষি অফিসের সঙ্গে মিলিয়ে নিন।')}</p></section>${g.sections.map(s=>guideSection(L(s.title),L(s.text))).join('')}<section class="card card-pad"><h2>${t('Pests, diseases & management','পোকা, রোগ ও ব্যবস্থাপনা')}</h2><p>${t('Inspect new growth and leaf undersides regularly. Open a relevant guide for symptoms, biological options and crop-specific chemical information; a listing is a monitoring aid, not a diagnosis.','নিয়মিত কচি বৃদ্ধি ও পাতার নিচ দেখুন। লক্ষণ, জৈব উপায় ও ফসলনির্দিষ্ট রাসায়নিক তথ্য জানতে সংশ্লিষ্ট নির্দেশিকা খুলুন; তালিকায় থাকা শনাক্তকরণের প্রমাণ নয়।')}</p>${relatedPests(g.pests)}</section><section class="card card-pad"><h2>${t('Sources & local planning','তথ্যসূত্র ও স্থানীয় পরিকল্পনা')}</h2><p>${t('Reviewed 9 November 2026. Keep records of variety, sowing date, inputs, pest observations, harvest and yield. Check seasonal district advisories before the next crop.','পর্যালোচনা: ৯ নভেম্বর ২০২৬। জাত, বপনের দিন, উপকরণ, বালাই পর্যবেক্ষণ, সংগ্রহ ও ফলনের হিসাব রাখুন। পরের ফসলের আগে জেলার মৌসুমি পরামর্শ দেখুন।')}</p>${librarySources(g.refs)}</section></div><aside class="stack"><div class="card card-pad"><div class="eyebrow">${t('Growing guide','চাষ নির্দেশিকা')}</div><h3>${t('From planting to harvest','রোপণ থেকে সংগ্রহ')}</h3><ol class="guide-index">${g.sections.map(s=>`<li>${esc(L(s.title))}</li>`).join('')}</ol>${link('aez',t('Explore agricultural zones','কৃষি অঞ্চল দেখুন'))}<button class="btn full" data-action="crop-help" data-id="${id}">${t('Prepare a crop question','ফসলের প্রশ্ন প্রস্তুত করুন')}</button></div></aside></div></div>`;}
function renderPests(){const all=[...pestData.map((p,i)=>({...p,type:'pests',key:'p'+i})),...diseases.map((p,i)=>({...p,type:'diseases',key:'d'+i}))];const results=all.filter(p=>(pestType==='all'||p.type===pestType)&&JSON.stringify([p.en,p.bn,PEST_GUIDES[p.key]]).toLowerCase().includes(pestQuery.trim().toLowerCase()));$('#pest-count').textContent=`${num(results.length)} ${t('results','টি ফলাফল')}`;$('#pest-results').innerHTML=results.length?`<div class="grid three">${results.map(p=>{const d=p[lang];return `<a class="card pest-card pest-guide-card" href="#pest/${p.key}" id="${p.key}">${p.images?.length?`<div class="pest-image"><img src="${esc(p.images[0])}" alt="${esc(d.name)}" loading="lazy" decoding="async" width="960" height="640"></div>`:''}<div class="card-pad"><span class="tag">${t(p.type==='pests'?'Pest / mite':'Disease / symptoms',p.type==='pests'?'পোকা / মাকড়':'রোগ / লক্ষণ')}</span><h3>${esc(d.name)}</h3><p class="sci">${esc(d.sci)}</p><p class="host-crop">${esc(d.crop)}</p><p class="pest-summary">${esc(d.damage)}</p><span class="link">${t('Symptoms & complete management','লক্ষণ ও বিস্তারিত ব্যবস্থাপনা')}${I('arrow')}</span></div></a>`}).join('')}</div>`:`<div class="empty">${t('No matches. Try another crop or symptom.','কিছু পাওয়া যায়নি। অন্য ফসল বা লক্ষণ লিখুন।')}</div>`;}